package com.lianxibu.site.repository.jobs;

import com.lianxibu.site.domain.protocol.*;
import java.time.*;
import java.time.temporal.TemporalAdjusters;
import java.util.*;
import javax.sql.DataSource;
import org.springframework.jdbc.core.JdbcTemplate;
import org.springframework.transaction.TransactionDefinition;
import org.springframework.transaction.support.TransactionSynchronizationManager;
import tools.jackson.databind.json.JsonMapper;

/** Full original report-ready native receipt. Its existence alone grants no body, visibility or publication authority. */
public final class JdbcReportCompletionReceipts {
    public record Ready(String rootId,String stage,long generation,String inputHash,String resultHash,ContentVersionKey version,long appliedRevision,Instant periodStart,Instant periodEnd,List<String> intentIds,Instant recordedAt,String payloadJson){
        public Ready{intentIds=List.copyOf(intentIds);}
        @Override public String toString(){return "OriginalReportCompletionReceipt[redacted]";}
    }
    private final JdbcTemplate sql;
    public JdbcReportCompletionReceipts(DataSource source){sql=new JdbcTemplate(Objects.requireNonNull(source));}
    public Ready read(String root){readonly();WireValues.id(root,false);String key="report-ready:"+root,id=JdbcFrozenInputs.stableId("report-ready",key);byte[] identity=HexFormat.of().parseHex(CanonicalJson.hash(CanonicalJson.Domain.IDENTITY,JsonMapper.shared().createObjectNode().put("record_kind","disposition").put("natural_key",key)));String target=JdbcFrozenInputs.canonical(JsonMapper.shared().createObjectNode().put("kind","logical_task").put("id",root));
        var rows=sql.query("SELECT id,record_kind,state,revision,call_count,max_attempts,priority_no,record_identity_hash,action_key_hash,target_type,CASE WHEN OCTET_LENGTH(target_key_json) BETWEEN 1 AND 1024 THEN target_key_json ELSE NULL END,target_key_hash,operator_id,reason,acted_at,created_at,updated_at,eligible_at,CASE WHEN OCTET_LENGTH(action_payload) BETWEEN 1 AND 16384 THEN action_payload ELSE NULL END,action_payload_hash,business_key,task_kind,target_id,root_job_id,intent_id,generation,task_type,logical_key,attempt_no,owner_job_id,purpose,stamp_id,part_no FROM jobs WHERE id=? OR action_key_hash=? OR record_identity_hash=? LIMIT 2",(r,n)->{
            String raw=r.getString(19);if(raw==null||r.getString(11)==null)throw invalid();raw=JdbcFrozenInputs.canonical(CanonicalJson.parse(raw));String actual=JdbcFrozenInputs.canonical(CanonicalJson.parse(r.getString(11)));Instant at=instant(r.getTimestamp(15,utc()));
            if(!id.equals(r.getString(1))||!"disposition".equals(r.getString(2))||!"applied".equals(r.getString(3))||number(r.getObject(4))!=0||number(r.getObject(5))!=0||r.getObject(6)!=null||number(r.getObject(7))!=0||!Arrays.equals(identity,r.getBytes(8))||!Arrays.equals(hash(key),r.getBytes(9))||!"report_result_ready".equals(r.getString(10))||!target.equals(actual)||!Arrays.equals(hash(actual),r.getBytes(12))||!"analysis-worker".equals(r.getString(13))||!"Report version completed".equals(r.getString(14))||!at.equals(instant(r.getTimestamp(16,utc())))||!at.equals(instant(r.getTimestamp(17,utc())))||!at.equals(instant(r.getTimestamp(18,utc())))||!Arrays.equals(hash(raw),r.getBytes(20))||!("disposition:"+HexFormat.of().formatHex(identity)).equals(r.getString(21))||!"disposition".equals(r.getString(22))||!id.equals(r.getString(23)))throw invalid();for(int field=24;field<=33;field++)if(r.getObject(field)!=null)throw invalid();return decode(root,raw,at);
        },id,hash(key),identity);if(rows.isEmpty())return null;if(rows.size()!=1)throw invalid();return rows.getFirst();
    }
    private static Ready decode(String root,String raw,Instant at){var body=CanonicalJson.parse(raw);var fields=Set.of("schema_version","root_id","input_hash","result_hash","stage","generation","content_id","applied_revision","period_start","period_end","content_version","intent_ids");WireValues.object(body,fields,fields);if(!"report-result-ready-v1".equals(WireValues.text(body.get("schema_version")))||!root.equals(WireValues.id(body.get("root_id"),false)))throw invalid();String stage=WireValues.text(body.get("stage"));if(!Set.of("daily_report","weekly_report","monthly_report").contains(stage))throw invalid();long generation=WireValues.nonnegativeInteger(body.get("generation")),revision=WireValues.nonnegativeInteger(body.get("applied_revision"));var version=ContentVersionKey.fromJson(body.get("content_version"));if(generation<1||revision<version.revision()||!"report".equals(version.contentKind())||!root.equals(version.inputJobId())||!version.contentId().equals(WireValues.id(body.get("content_id"),false)))throw invalid();Instant first=WireValues.utcMicroseconds(body.get("period_start")),end=WireValues.utcMicroseconds(body.get("period_end"));var zone=ZoneId.of("Asia/Shanghai");LocalDate start=first.atZone(zone).toLocalDate(),last=end.atZone(zone).toLocalDate().minusDays(1);if(!start.atStartOfDay(zone).toInstant().equals(first)||!last.plusDays(1).atStartOfDay(zone).toInstant().equals(end)||end.isAfter(at))throw invalid();boolean natural=switch(stage){case "daily_report"->start.equals(last);case "weekly_report"->last.getDayOfWeek()==DayOfWeek.SUNDAY&&start.equals(last.minusDays(6));default->last.getDayOfMonth()==last.lengthOfMonth()&&start.equals(last.withDayOfMonth(1));};if(!natural)throw invalid();var values=body.get("intent_ids");if(values==null||!values.isArray())throw invalid();var intents=new ArrayList<String>();for(var value:values)intents.add(WireValues.id(value,false));List<String> expected=stage.equals("daily_report")?List.of(intent("weekly",last.with(TemporalAdjusters.nextOrSame(DayOfWeek.SUNDAY))),intent("monthly",last.withDayOfMonth(last.lengthOfMonth()))):List.of();if(!expected.equals(intents))throw invalid();return new Ready(root,stage,generation,WireValues.sha256(body.get("input_hash")),WireValues.sha256(body.get("result_hash")),version,revision,first,end,intents,at,raw);}
    private static String intent(String type,LocalDate end){return JdbcFrozenInputs.stableId("intent","report:"+type+":"+end+":1");}
    private static byte[] hash(String value){return JdbcGenerationLineage.hash(value);}
    private static long number(Object value){if(!(value instanceof Number))throw invalid();try{long result=new java.math.BigInteger(value.toString()).longValueExact();if(result<0||result>CanonicalJson.MAX_SAFE_INTEGER)throw invalid();return result;}catch(RuntimeException bad){throw invalid();}}
    private static Calendar utc(){return Calendar.getInstance(TimeZone.getTimeZone("UTC"));}
    private static Instant instant(java.sql.Timestamp value){if(value==null||value.getNanos()%1000!=0)throw invalid();return value.toInstant();}
    private static void readonly(){if(!TransactionSynchronizationManager.isActualTransactionActive()||!TransactionSynchronizationManager.isCurrentTransactionReadOnly()||!Integer.valueOf(TransactionDefinition.ISOLATION_REPEATABLE_READ).equals(TransactionSynchronizationManager.getCurrentTransactionIsolationLevel()))throw invalid();}
    private static IllegalStateException invalid(){return new IllegalStateException("original native report completion receipt unavailable");}
}
